51: /// Parse a direct spec or resolver-backed compose document into kernel AST.
52: ///
53: /// # Errors
54: ///
55: /// Returns [`CoreError`] for parsing, dependency resolution, name rewriting,
56: /// or unsupported top-level documents.
57: pub fn parse_kernel_source(
58:     source: &str,
59:     resolver: &dyn FileResolver,
60: ) -> Result<KernelSpec, CoreError> {
61:     let parsed = parse_document(SourceFile::new(source))?;
62:     let mut kernel = match parsed.surface {
63:         SurfaceDocument::Spec(spec) => crate::lower_direct_spec(spec),
64:         SurfaceDocument::Business(business) => crate::lower_business(business),
65:         SurfaceDocument::Requirements(requirements) => crate::lower_requirements(requirements),
66:         SurfaceDocument::Governance(governance) => crate::lower_governance(governance),
67:         SurfaceDocument::Db(system) => crate::lower_db(&system),
68:         SurfaceDocument::Domain(domain) => crate::lower_domain(&domain),
69:         SurfaceDocument::AiComponent(component) => crate::lower_ai_component(component),
70:         SurfaceDocument::Compose(compose) => lower_compose(compose, resolver),
71:         SurfaceDocument::Refinement(_) | SurfaceDocument::Agent(_) => Err(CoreError {
72:             message: "top-level document has not reached the kernel lowering gate".to_owned(),
73:             line: 1,
74:             column: 1,
75:             origin: None,
76:             name_resolution: false,
77:         }),
78:     }?;
79:     kernel
80:         .annotations
81:         .extend(crate::SPEC_TARGET, parsed.annotations);
82:     Ok(kernel)
83: }
