85: /// Parse and lower source while attaching the caller-known root file identity
86: /// to internal origins and diagnostics.
87: ///
88: /// # Errors
89: ///
90: /// Returns [`CoreError`] with the same language contract as
91: /// [`parse_kernel_source`], enriched with the supplied source identity.
92: pub fn parse_kernel_source_with_file(
93:     source: &str,
94:     resolver: &dyn FileResolver,
95:     source_file: impl AsRef<str>,
96: ) -> Result<KernelSpec, CoreError> {
97:     let source_file = source_file.as_ref();
98:     parse_kernel_source(source, resolver)
99:         .map(|kernel| kernel.with_source_file(source_file))
100:         .map_err(|error| error.with_source_file(source_file))
101: }
