103: #[derive(Clone)]
104: struct Component {
105:     alias: String,
106:     names: ComponentNames,
107:     spec: SurfaceSpec,
108: }
109: 
110: #[derive(Clone, Default)]
111: struct ComponentNames {
112:     consts: HashSet<String>,
113:     types: HashSet<String>,
114:     state: HashSet<String>,
115:     actions: HashSet<String>,
116:     properties: HashSet<String>,
117: }
118: 
119: impl ComponentNames {
120:     fn collect(spec: &SurfaceSpec) -> Self {
121:         let mut names = Self::default();
122:         for item in &spec.items {
123:             match item {
124:                 SpecItem::Const { name, .. } => {
125:                     names.consts.insert(name.clone());
126:                 }
127:                 SpecItem::Type { name, .. }
128:                 | SpecItem::Enum { name, .. }
129:                 | SpecItem::Struct { name, .. } => {
130:                     names.types.insert(name.clone());
131:                 }
132:                 SpecItem::State(fields) => {
133:                     names
134:                         .state
135:                         .extend(fields.iter().map(|field| field.name.clone()));
136:                 }
137:                 SpecItem::Action { name, .. } => {
138:                     names.actions.insert(name.clone());
139:                 }
140:                 SpecItem::Invariant { name, .. }
141:                 | SpecItem::Trans { name, .. }
142:                 | SpecItem::Reachable { name, .. }
143:                 | SpecItem::Until { name, .. }
144:                 | SpecItem::Unless { name, .. }
145:                 | SpecItem::LeadsTo { name, .. } => {
146:                     names.properties.insert(name.clone());
147:                 }
148:                 _ => {}
149:             }
150:         }
151:         names
152:     }
153: }
